-- Monotonic whole-set checkpoint for actual tag filter/page/count inputs.
CREATE TABLE knowledge_tag_statistics_scope_versions (tenant_id BIGINT NOT NULL CHECK(tenant_id>0),knowledge_base_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),PRIMARY KEY(tenant_id,knowledge_base_id));
INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) SELECT tenant_id,id,1 FROM knowledge_bases;
CREATE TRIGGER tag_statistics_knowledge_bases_insert AFTER INSERT ON knowledge_bases BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_knowledge_bases_update AFTER UPDATE ON knowledge_bases BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_knowledge_bases_delete AFTER DELETE ON knowledge_bases BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_knowledge_tags_insert AFTER INSERT ON knowledge_tags BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_knowledge_tags_update AFTER UPDATE ON knowledge_tags BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_knowledge_tags_delete AFTER DELETE ON knowledge_tags BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_knowledges_insert AFTER INSERT ON knowledges BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_knowledges_update AFTER UPDATE ON knowledges BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_knowledges_delete AFTER DELETE ON knowledges BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_chunks_insert AFTER INSERT ON chunks BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_chunks_update AFTER UPDATE ON chunks BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_chunks_delete AFTER DELETE ON chunks BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER tag_statistics_relations_insert AFTER INSERT ON knowledge_tag_relations BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) SELECT tenant_id,knowledge_base_id,1 FROM knowledges WHERE id=NEW.knowledge_id UNION SELECT tenant_id,knowledge_base_id,1 FROM knowledge_tags WHERE id=NEW.tag_id ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1;  END;
CREATE TRIGGER tag_statistics_relations_update AFTER UPDATE ON knowledge_tag_relations BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) SELECT tenant_id,knowledge_base_id,1 FROM knowledges WHERE id=OLD.knowledge_id UNION SELECT tenant_id,knowledge_base_id,1 FROM knowledge_tags WHERE id=OLD.tag_id ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) SELECT tenant_id,knowledge_base_id,1 FROM knowledges WHERE id=NEW.knowledge_id UNION SELECT tenant_id,knowledge_base_id,1 FROM knowledge_tags WHERE id=NEW.tag_id ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1;  END;
CREATE TRIGGER tag_statistics_relations_delete AFTER DELETE ON knowledge_tag_relations BEGIN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) SELECT tenant_id,knowledge_base_id,1 FROM knowledges WHERE id=OLD.knowledge_id UNION SELECT tenant_id,knowledge_base_id,1 FROM knowledge_tags WHERE id=OLD.tag_id ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1;  END;
